<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class ComplianceController extends Controller{
 private function ok(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||$r->user()->hasRole('academic_head'),403);}
 private function item($level,$area,$title,$count,$route,$basis='local'){return compact('level','area','title','count','route','basis');}
 public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$items=[];
 $unapproved=DB::table('curriculum_plans')->where('academic_period_id',$p->id)->where('approval_status','!=','approved')->count();if($unapproved)$items[]=$this->item('warning','Рабочие программы','Не утверждены рабочие программы',$unapproved,'curriculum.index','local');
 $noTopics=DB::table('curriculum_plans as cp')->where('cp.academic_period_id',$p->id)->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('curriculum_topics as ct')->whereColumn('ct.curriculum_plan_id','cp.id'))->count();if($noTopics)$items[]=$this->item('warning','КТП','Рабочие программы без тематического плана',$noTopics,'curriculum.index','local');
 $hours=DB::table('load_requirements as lr')->where('lr.academic_period_id',$p->id)->get();$def=0;$over=0;foreach($hours as $h){$q=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$h->study_group_id,'subject_id'=>$h->subject_id]);if($h->study_type_id)$q->where('study_type_id',$h->study_type_id);$bal=(float)$h->required_hours-(float)$q->sum('hours_total');if($bal>.01)$def++;if($bal<-.01)$over++;}if($def)$items[]=$this->item('critical','Нагрузка','Недораспределены требуемые часы',$def,'tarification.index','local');if($over)$items[]=$this->item('warning','Нагрузка','Распределено часов больше потребности',$over,'tarification.index','local');
 $vac=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'vacant'=>1])->count();if($vac)$items[]=$this->item('critical','Нагрузка','Нагрузка без преподавателя',$vac,'tarification.index','local');
 $debts=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->whereRaw('a.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=a.attestation_sheet_id and a2.student_id=a.student_id)')->where('a.passed',0)->count();if($debts)$items[]=$this->item('critical','Аттестация','Незакрытые академические задолженности',$debts,'attestation.index','federal');
 $commission=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where('sh.academic_period_id',$p->id)->where('a.attempt_no',2)->whereNotExists(fn($q)=>$q->select(DB::raw(1))->from('attestation_commission_members as m')->whereColumn('m.attestation_attempt_id','a.id'))->count();if($commission)$items[]=$this->item('critical','Аттестация','Вторые пересдачи без состава комиссии',$commission,'attestation.index','federal');
 $practice=DB::table('practice_placements')->where('academic_period_id',$p->id)->where(function($q){$q->whereNull('result')->orWhereNotIn('result',['passed','зачтено','5','4','3']);})->count();if($practice)$items[]=$this->item('warning','Практика','Практика без положительного результата',$practice,'practice.index','local');
 $gia=DB::table('gia_student_results as gr')->join('gia_campaigns as c','c.id','=','gr.gia_campaign_id')->where('c.academic_period_id',$p->id)->where('gr.admission_status','blocked')->count();if($gia)$items[]=$this->item('critical','ГИА','Выпускники заблокированы для ГИА',$gia,'gia.index','federal');
 $grad=DB::table('graduation_records')->where('academic_period_id',$p->id)->where('readiness','blocked')->count();if($grad)$items[]=$this->item('critical','Выпуск','Выпускники не готовы к выпуску',$grad,'graduation.index','local');
 $rector=DB::table('study_groups')->where('active',1)->whereNull('source_id')->count()+DB::table('teachers')->where('active',1)->whereNull('source_id')->count()+DB::table('subjects')->whereNull('source_id')->count();if($rector)$items[]=$this->item('warning','Rector','Объекты без Rector ID',$rector,'rector.index','integration');
 $critical=collect($items)->where('level','critical')->sum('count');$warnings=collect($items)->where('level','warning')->sum('count');$groups=DB::table('study_groups as g')->leftJoin('specialties as sp','sp.id','=','g.specialty_id')->where('g.active',1)->select('g.*','sp.code specialty_code','sp.name specialty_name')->orderBy('g.name')->get();foreach($groups as $g){$g->debts=DB::table('attestation_attempts as a')->join('attestation_sheets as sh','sh.id','=','a.attestation_sheet_id')->where(['sh.academic_period_id'=>$p->id,'sh.study_group_id'=>$g->id])->whereRaw('a.attempt_no=(select max(a2.attempt_no) from attestation_attempts a2 where a2.attestation_sheet_id=a.attestation_sheet_id and a2.student_id=a.student_id)')->where('a.passed',0)->count();$g->vacancies=DB::table('teaching_load_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id,'vacant'=>1])->count();$g->programs=DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id])->count();$g->unapproved=DB::table('curriculum_plans')->where(['academic_period_id'=>$p->id,'study_group_id'=>$g->id])->where('approval_status','!=','approved')->count();}
 return view('academic-office.compliance',compact('p','items','critical','warnings','groups'));}
}